insert into services (title, description, icon, sort_order) values
('Website Development','Fast, accessible websites for businesses and personal brands that explain your offer and turn visitors into enquiries, bookings or sales. Design, development, content management, search setup and launch, with English and French versions when you need them.','code',0),
('App Development','Custom web and mobile apps built around how your business actually runs: customer portals, booking and ordering, dashboards, point of sale and internal tools, with the interface, API and database designed together.','smartphone',1),
('Business Automation & AI','Automated workflows that connect the tools you already use, so leads, invoices, bookings and reports move on their own. Where it helps, AI assistants that answer from your own data, with clear limits and human hand-offs.','workflow',2),
('Support & Hosting','Hosting, domains, email, integrations and the fixes that keep everything running after launch. We trace issues to the cause, explain the fix and document it, on call-outs or a monthly plan.','cpu',3);
insert into skills (name, level, sort_order) values
('Next.js & React',82,0),('React Native',75,1),('TypeScript',78,2),('Supabase & Postgres',76,3),('WordPress',90,4),('Framer',88,5),('Workflow Automation & APIs',80,6),('AI Assistants & Retrieval',75,7),('Hosting & Technical Support',88,8);
insert into portfolio_items (title, category, description, image_url, video_url, link, is_video, sort_order) values
('Efuniture','App Development','Furniture is the hardest thing to sell on a phone: the buyer needs scale, finish and room context before spending serious money, and a grid of thumbnails gives none of it. Efuniture is a furniture shopping app built around that problem, opening on a sign-in that offers Google, Apple or guest browsing rather than a wall, then letting someone shortlist and return to a saved basket. Built as a mobile-first product interface, so the photography does the selling at the size it is actually viewed.','/portfolio/apps/efurniture.webp','/portfolio/videos/efurniture.mp4','https://efuniture.vercel.app/login',false,0),
('Rechx','App Development','An app people open several times a day lives or dies at the sign-in screen, and a password form alone loses the ones in a hurry. Rechx offers the alternatives a returning user actually wants: email or phone, Face ID, or a one-time code by SMS, with remember-me and recovery sitting where a stuck user looks. The account layer is the product foundation, so it is built first and built properly.','/portfolio/apps/rechx.webp','/portfolio/videos/rechx.mp4','https://rechx-sooty.vercel.app/#/login',false,1),
('FoxyAI','Websites','Most AI consultancies sell a pilot that never reaches production, so the buyer has heard the pitch before and discounts it. FoxyAI is positioned against that: systems deployed inside the business, with processes redesigned and data connected so a team can actually use them. The site sells on operators rather than slideware, with workflows deployed and industries served as figures, the method broken into strategy, automation and deployment, and case work carrying the proof.','/portfolio/websites/foxyai.webp','/portfolio/videos/foxyai.mp4','https://foxyai-phi.vercel.app',false,2),
('Leadloop','Websites','Outbound sales dies in the gap between sending an email and answering the reply, which is where a small team runs out of hours. Leadloop sells an AI agent that closes that gap: paste a website, it works out the buyer segments, writes each prospect a personal email, answers what comes back and puts the meeting on a calendar. The site has to make an autonomous agent feel safe to hand your pipeline to, so it shows a real reply thread being handled, what is working and where budget goes, and a setup measured in one afternoon rather than a quarter.','/portfolio/websites/leadloop.webp',null,'https://leadloop-mu.vercel.app',false,3),
('BizGrowth','Websites','A growing business ends up with analytics in one tool, campaigns in another and automation nobody owns, so nothing can be compared. BizGrowth is the product site for a workspace that puts them together, and it sells on the dashboard rather than the promise: traffic split by source, revenue tracked month on month, leads and ROI as live figures. Plans are priced on the page, the signup is free to start, and every section drives at the same action.','/portfolio/websites/bizgrowth.webp','/portfolio/videos/bizgrowth.mp4','https://bizgrowth-psi.vercel.app',false,4),
('Abujacars','Websites','Buying a used car in Nigeria is a trust problem before it is a price problem: is the car sound, are the papers real, and will the seller still answer next week. Abujacars answers all three on the page. Every car carries a 150-point inspection and customs and papers verification, financing and nationwide delivery are stated up front, and sellers get a cash offer within 24 hours. The fleet is browsable by brand and type with real photography, so a buyer shortlists before anyone picks up a phone.','/portfolio/websites/abujacars.webp','/portfolio/videos/abujacars.mp4','https://abujacars-topaz.vercel.app',false,5),
('FitsX','App Development','Fashion shoppers abandon an app at the sign-in screen, so that screen has to do more than collect a password. FitsX opens on a one-tap path: email, Google or Apple, a skip for browsing first, and a clear route to sign up rather than a dead end. Behind it sits the shopping app itself, built in React Native with accounts, saved items and checkout, so a returning customer is two taps from the basket they left behind.','/portfolio/apps/fitsx.webp','/portfolio/videos/fitsx.mp4','https://fitsx.vercel.app/login',false,6),
('Foodx','Websites','A bakery selling through Instagram posts cannot show a menu, take an order or hold a basket, so every sale costs a conversation. Foodx is the storefront for a Lekki Phase 1 bakery and coffee bar: donuts, cheesecakes, shakes and iced coffee photographed properly, priced in naira, added to a cart and ordered. Location and opening details sit where someone deciding on a walk-in looks, and the menu doubles as the thing search engines can actually read.','/portfolio/websites/foodx.webp','/portfolio/videos/foodx.mp4','https://foodx-three.vercel.app',false,7),
('NeoTech','Websites','Selling immersive technology on a flat web page is its own problem: describe VR in paragraphs and it sounds like every other agency. NeoTech demonstrates instead, with 3D built in React Three Fiber running in the browser, so the capability is the proof. Around it sit the services a buyer is actually choosing between, VR development, AI avatars and gaming, each written plainly enough for the budget holder rather than the engineer.','/portfolio/websites/neotech.webp','/portfolio/videos/neotech.mp4','https://neotech-ruddy-eight.vercel.app',false,8),
('Cryptox','Websites','A finance team will not move company money onto a trading platform that was designed for a retail speculator. Cryptox is the product site for one built for businesses, and the page is organised around the objections a treasurer raises: who can approve a trade, whether it passes compliance, what it costs, and who answers at 3am. Role-based permissions and shared wallets, KYC and AML workflows with exportable audit reports, transparent pricing with no hidden spread, a named account manager, and a first-quarter plan laid out week by week from onboarding to scale.','/portfolio/websites/cryptox.webp','/portfolio/videos/cryptox.mp4','https://cryptox-omega-nine.vercel.app',false,9),
('InteriorX','Websites','Interior design is bought on evidence that the firm has done it before, and most studio sites bury the work behind a philosophy statement. InteriorX leads with the rooms: completed projects by type, residential through commercial, landscape and renovation, with the process broken into the four stages a client is actually agreeing to, from first consultation to final handover. Named designers with their specialisms, a rated client review, years in business and project count carry the credibility, and the quote request sits in reach of every section.','/portfolio/websites/interiorx.webp','/portfolio/videos/interiorx.mp4','https://interiorx-seven.vercel.app',false,10),
('Cardx','Websites','Someone paid in three currencies loses money twice: once to the exchange rate and again to fees nobody itemises. Cardx is the product site for a multi-currency account that removes both, and it has to make a stranger trust it with their salary. Every claim is a number rather than an adjective: 150+ currencies at the real rate, zero FX fees, instant virtual cards, spending categorised as it happens, card frozen in a tap. Signup is three steps on the page, and a real customer story carries the proof.','/portfolio/websites/cardx.webp',null,'https://cardx-chi.vercel.app',false,11),
('Lume','Websites','Lighting is bought on feeling and returned on disappointment, which makes the photography the product. Lume is a storefront for sculptural lamps built around that: every piece shot lit against dark, filtered by ambient or task so a buyer shops by the job the lamp has to do, priced on the card so nothing is hidden, with the warranty, free shipping and 30-day returns stated where the hesitation actually happens.','/portfolio/websites/lume.webp',null,'https://lume-topaz-six.vercel.app',false,12),
('Travel360','Websites','Planning a trip means four tabs: one for flights, one for hotels, one for tours, one to check the price was fair. Travel360 puts the search itself at the top of the page, with flights, hotels, tours and packages in one control and real dates, destinations and traveller counts. Below it, destinations priced from, handpicked tours, and the guarantees that settle a nervous first booking: best price, secure payment, and support at any hour.','/portfolio/websites/travel360.webp',null,'https://travel360-beige.vercel.app',false,13),
('Luxury Watches','Websites','A single-product seller does not need a shop, it needs one page that closes. This landing page sells one matte black watch: the price up front, the detail shots that justify it, colour chosen on the page, quantity set, and the order handed straight to WhatsApp with the details already filled in, so the buyer taps send instead of typing out what they want. Three steps, stated plainly, for a market that already buys and pays through chat.','/portfolio/websites/luxurywatches.webp',null,'https://luxurywatches-bay.vercel.app',false,14),
('Xtend','App Development','Managing staff across multiple stores means knowing who has arrived, where they are working and which issues need attention. Xtend brings GPS-backed attendance, staff movement, store visits, marketer reports and stock counts into one operations app. The admin dashboard shows clock-ins, late arrivals, location coverage and open alerts at a glance, with staff and team management, analytics and an Ask Xtend assistant available from the same workspace.','/portfolio/apps/xtend.webp',null,'https://xtend-brown.vercel.app',false,15),
('Lume','Websites','Choosing a lamp is as much about the atmosphere it creates as its specifications. Lume is a lighting storefront built around that decision: warm product photography, a sculptural hero piece and a collection organised into ambient and task lighting with prices visible throughout. A dark palette and restrained gold accents let the lamps carry the page, while shopping, account and contact links stay within reach.','/portfolio/websites/lume.webp',null,'https://lume-topaz-six.vercel.app/',false,16),
('Travel360','Websites','Planning a trip means comparing destinations, flights, hotels and tours without losing track of the experience you want. Travel360 brings those choices into one travel website, pairing destination photography with a prominent search panel for dates, travellers and travel type. Destination cards show starting prices, while trip inspiration, support information and a newsletter give visitors clear ways to keep exploring.','/portfolio/websites/travel360.webp',null,'https://travel360-beige.vercel.app/',false,17),
('Luxury Watches','Websites','A watch buyer wants to see the details, know the price and place an order without a long conversation. Luxury Watches is a product website centred on a matte black unisex watch, with close-up photography, lifestyle images, colour choices and clear naira pricing. The order form collects the buyer''s details, colour and quantity, then prepares a WhatsApp message so the seller can confirm the order and arrange delivery.','/portfolio/websites/luxury-watches.webp',null,'https://luxurywatches-bay.vercel.app/',false,18),
('Cardx','Websites','A banking product page needs to make everyday benefits easy to understand. Cardx presents its metal card, virtual cards and budgeting tools through a bold monochrome layout with orange accents and a distinctive mechanical hero illustration. Product benefits, a three-step onboarding overview and a customer story lead visitors towards opening an account, with currency support, spending insights and card controls explained along the way.','/portfolio/websites/cardx.webp',null,'https://cardx-chi.vercel.app/',false,19),
('Bikenation','Websites','A superbike buyer decides on the exact machine, the exact colour and the exact price, and most dealer sites show a grid of stock photos with ''call for price''. Bikenation puts the whole decision on the page: every bike priced with its real specs (power, top speed, 0-100, engine and mileage), a colour configurator that prices each option as you pick it, riding gear sold alongside, and a test ride booked from the same page. Each bike is inspected across 130 points, and the site says so where a buyer spending $32,000 needs to read it.','/portfolio/websites/bikenation.webp',null,'https://bikenation-fawn.vercel.app',false,20),
('ChurchX','App Development','A church knows roughly how many people came on Sunday and almost nothing else: who the first-timer was, whether anyone called them, which member stopped showing up three months ago. ChurchX is the management app that closes those gaps. A visitor is registered in seconds from a phone at the door, follow-ups are assigned to a real person and recorded, members drifting away surface before they are gone, and Sunday check-in, giving records and the reports leadership asks for all come from the same place.','/portfolio/apps/churchx.webp',null,'https://churchx-one.vercel.app/login',false,21),
('OBSpad','App Development','Live production software assumes a laptop, a mouse and a desk, which is not what a church media volunteer or a solo streamer actually has. OBSpad is my own app: it turns an Android tablet or iPad into a full production desk modelled on OBS Studio, rebuilt for fingers with big targets, pinch to scale and long-press menus. Scenes and Studio Mode preview, chroma key and audio filters, USB capture cards and webcams, output to a second screen or NDI, and going live on Facebook, YouTube or Twitch with just a stream key.','/portfolio/apps/obspad.webp',null,'https://obspad.vercel.app',false,22),
('Airspare.Ai','Websites','Nobody knows whether today is the right day to book a flight, so people either buy too early or watch the fare climb. Airspare.Ai is the product site for an AI flight platform that answers that question: real-time fare predictions telling you when to book, 200+ airlines compared in seconds, route and seat suggestions, price-drop alerts on favourite routes, and loyalty points tracked live and redeemable at checkout. The page has to make an AI claim credible, so every feature is shown as a real screen with the number it produces.','/portfolio/websites/airspare.webp',null,'https://airspare.vercel.app',false,23),
('RentCarsNG','Websites','Renting a car in Nigeria usually means calling around, haggling, and finding out at pickup what the car actually looks like. RentCarsNG replaces that with a booking flow: filter by city, type and dates across Lagos, Abuja, Port Harcourt, Ibadan and Enugu, see the real fleet with daily naira pricing, choose self-drive or chauffeur, and confirm and pay online. Branch locations on a map, customer reviews and an off-road fleet for weddings and long trips do the convincing before anyone picks up a phone.','/portfolio/websites/rentcarsng.webp',null,'https://rentcars-alpha.vercel.app',false,24),
('PetNG','Websites','Nigerian pet owners buy food and toys from Instagram sellers with no prices, no returns and no way to know a product is safe. PetNG is the e-commerce storefront that fixes it: shop by dog or cat, browse real categories with naira pricing, vet-approved products, free delivery over a threshold, 30-day returns, same-day dispatch and paw points on every order. Reviews from real owners and a care blog carry the trust that a first-time buyer needs before paying online.','/portfolio/websites/petng.webp',null,'https://petng-kappa.vercel.app',false,25),
('AgricX','Websites','A farmer considering a spraying drone is comparing a serious capital purchase against a spec sheet he cannot read. AgricX sells it in his terms: cover more ground with less water and less chemical, with each drone listed by payload, flow rate and the job it does, from precision spraying and crop mapping to field scouting and variable-rate application. Pricing, pilot training, dealer locations and support are all on the page, so the buyer can get to a decision without a sales call.','/portfolio/websites/agricx.webp',null,'https://agricx-five.vercel.app',false,26),
('Finshield','Websites','People do not hand their money to a new financial app because the copy says it is secure. This product site for a fintech earns it instead: fraud alerts that catch a suspicious charge before the customer notices, real-time monitoring, zero liability, 24,000 partner ATMs and 2% cashback, each stated as a number rather than a promise. Apple Pay, Google Pay and partner logos sit where a cautious visitor looks for proof, and every section drives at one action: open the account.','/portfolio/websites/finshield.webp',null,'https://finshield-alpha.vercel.app',false,27),
('CONTX','Websites','A shipper choosing a cargo partner wants three answers before enquiring: can you move it, where can you move it, and where is it now. CONTX answers all three on the page. Sea, air and road freight laid out side by side, a world map of locations to buy, sell or lease containers, container specifications with prices, and shipment tracking plus a quote calculator in reach throughout. Twenty-plus years of fleet numbers carry the credibility that a first-time enquiry needs.','/portfolio/websites/contx.webp',null,'https://contx-theta.vercel.app',false,28),
('Vik Homes','Websites','House hunting falls apart when listings live in agent phone calls and nobody can filter by what actually matters. Vik Homes is the property platform that fixes that: search by city, property type and price, browse villas, houses and cottages with real photography and verified listings, and move from search to viewing to keys in three clear steps. Local agents, upfront pricing with no hidden fees, and a list-your-home path for sellers make it work from both sides of the deal.','/portfolio/websites/vikhomes.webp',null,'https://vikhomes.vercel.app',false,29),
('SchoolHub — School Admin App','App Development','A school''s admin staff carry the term in their heads and on paper: who is enrolled, who was present, what each parent still owes. This is the SchoolHub admin app they use instead. Attendance is taken per class arm in one pass, assessments carry CA and exam weighting through to a printable report card, fees show billed against collected with every unsettled invoice named, and enrollment, guardians, staff and messaging sit in the same place. A school admin sees only their own school; a group switches between them from the same login.','/portfolio/apps/schoolhub-app.webp',null,'https://schoolhub-sigma.vercel.app/login',false,30),
('Xpel POS','App Development','A beauty retailer running the till on a notebook cannot tell you what sold, what is about to run out, or whether the cash drawer balances at closing. Xpel POS is the app that runs the counter instead: sales rung up in a few taps, inventory and restock alerts tied to every sale, shifts opened and cashed up against counted cash, promotions and customer records, and transfers between shop and warehouse. Cash, transfer and card are each recorded and reconciled, an activity log covers who did what, and it installs to the device and keeps selling when the network drops.','/portfolio/apps/xpel-pos.webp',null,'https://xpel-pos.vercel.app',false,31),
('onefitness','Websites','Most fitness sites sell a membership and leave the person to work out what to actually do on Monday. onefitness starts from the goal instead: a weekly plan built around the member''s experience and the equipment they have, meal guidance with vegan, non-vegan and allergy-friendly options costed by calories, six training styles to pick from, and workshops and retreats bookable from the page. The first week is free in exchange for an email, so the visitor tries the programming before deciding on it.','/portfolio/websites/onefitness.webp',null,'https://onefitness-theta.vercel.app',false,32),
('SchoolHub','Websites','Most schools run on a spreadsheet per teacher, a fee book in the bursary and a WhatsApp group for everything else, so nobody can say what a pupil owes or scored without asking three people. SchoolHub is one system for the whole school: enrolment tied to a class arm and term, an attendance register built for a cheap phone on a bad network, CA and exam weighting that produces a printable report card, computer-based tests marked server-side, invoices paid through Paystack, Flutterwave, Remita or Stripe, and a pupil portal for results and fees. Groups run many schools on one database with row-level security, and every change lands in an audit log.','/portfolio/websites/schoolhub.webp',null,'https://schoolhub-sigma.vercel.app',false,33),
('Deem Hospital','Websites','A patient choosing a hospital wants to know three things before they call: can I see the right specialist, will my HMO cover it, and how fast can I be seen. This site for a Lagos multi-specialty hospital answers all three on the way down the page: consultants listed by discipline with direct booking and no referral, the HMOs accepted shown in full, on-site diagnostics with results inside 24 hours, a 24/7 emergency line pinned to the header, and health guidance written by the consultants themselves so the hospital earns the visit before it asks for it.','/portfolio/websites/deem-hospital.webp',null,'https://deem-hospital.vercel.app',false,34),
('Jhflogistics','Websites','Freight goes wrong in the handovers, so a shipper who uses one company for sea, another for customs and a third for the last mile spends the week chasing whoever had it last. This site for a Lagos freight company sells the opposite: one partner owning booking, customs, warehousing and final-mile delivery under a single tracked reference. Maritime, land and air services are laid out side by side, a quote form captures the lane and cargo detail needed to price it, real case studies carry the proof, and freight tracking sits in reach of every page.','/portfolio/websites/jhflogistics.webp',null,'https://jhflogistics.vercel.app',false,35),
('Everything Food','Websites','A restaurant that only takes orders by phone loses the customer who wants to see the menu and the price before calling. Everything Food is the site for an Abuja kitchen serving jollof, suya, pepper soup and swallow: a filterable menu with naira prices and ratings up front, weekend deals, a clear order-it-in, eat-it-here or track-your-order path, table booking and a Friday-menu newsletter, so a hungry visitor goes from browsing to ordering without picking up the phone.','/portfolio/websites/everything-food.webp',null,'https://everything-food-eta.vercel.app',false,36),
('Ajusti','Websites','Most Nigerian fashion sellers live in Instagram DMs, so a buyer can''t browse the range, check a price or trust the fit before paying. Ajusti is the storefront that fixes that for Ankara, adire, bags and shoes: shop-by-category browsing, clear naira pricing with sale markdowns, made-to-measure tailoring up front, real customer reviews, and checkout through Paystack, Flutterwave, bank transfer or pay on delivery, so a first-time buyer has every reason to order instead of asking.','/portfolio/websites/ajusti.webp',null,'https://ajusti-ten.vercel.app',false,37),
('Gateway Lodge Group','Websites','A hospitality brand with several properties usually ends up as one generic site and a shared inbox, so no guest can tell what makes any single property worth booking. Gateway Lodge Group needed the opposite: one group site for brand and cross-property discovery, plus a dedicated microsite for each property (Lakeside, Tamale, Nova Ridge) with its own gallery, facilities and direct-booking flow, so a guest lands on the exact property they''re deciding on and can book it in a few clicks.','/portfolio/websites/gateway-lodge-group.webp',null,'https://www.gatewaylodgegroup.com',false,38),
('NexaConnect','Websites','Support inboxes drown in the same three questions: where is my order, how much is delivery, why was I charged twice. NexaConnect answers them instantly, and only from the company''s published policies and the customer''s real order record, so it never invents a refund promise the business has to honour. The team stops repeating itself and only handles the cases that actually need a human.','/portfolio/websites/nexaconnect.webp',null,'https://nexaconnect-pi.vercel.app',false,39),
('Finbolt','Websites','Nobody hands a stranger their business money because the copy says trust us. This product site for a payments platform earns it on the page: one clear promise up front (invoices, cards, transfers and payouts settled in minutes), proof right under it, and separate paths for start-ups, freelancers and enterprises so each visitor sees their own situation instead of a generic pitch, then signs up.','/portfolio/websites/finbolt.webp',null,'https://finbolt-nu.vercel.app',false,40),
('Vifug Lyrics','Websites','A product website for a live lyrics and Bible projection app built for churches. Designed to explain a feature-dense, technical product (offline-first, NDI, OBS, multi-language auto-follow) clearly enough for a media volunteer to trust it and download it.','/portfolio/websites/vifug-lyrics.webp',null,null,false,41),
('Fastora','Websites','A brand and communications strategy agency website featuring positioning, case studies, and a clear service breakdown designed to make complex brand work easy to understand and trust.','/portfolio/websites/fastora.webp',null,'https://fastora.africa',false,42),
('Energy Conseil Global','Websites','A corporate website for an energy consultancy whose buyers are institutional. Built around a restrained, authoritative layout that puts credentials and service scope where a procurement reader looks first.','/portfolio/websites/energy-conseil.webp',null,'https://energyconseilglobal.com',false,43),
('Rocabat','Websites','A website for a construction and building-services firm. The project showcase carries the credibility here, so the layout is built around image-led case entries with the services structured underneath.','/portfolio/websites/rocabat.webp',null,'https://rocabat.com',false,44),
('BrandLift','Websites','A brand-building and marketing platform where I built the entire front end: marketing site, authenticated dashboard and the sign-up flow between them. The hard part was keeping one visual language across a bold marketing page and a dense product UI.','/portfolio/websites/brandlift.webp',null,'https://brandlift-omega.vercel.app',false,45),
('Xpel Beauty NG','Websites','An e-commerce storefront for a beauty brand, paired with the hub for its social campaigns. Product imagery does the selling, so the build prioritises fast image loading and a checkout path with nothing in the way.','/portfolio/websites/xpel-beauty.webp',null,'https://xpelbeauty.vercel.app',false,46),
('Oasis Orchard Technologies','Websites','A marketing website for a VoIP reseller. The challenge was explaining a technical product to non-technical buyers, solved with plain-language tier comparisons and feature breakdowns instead of a spec dump.','/portfolio/websites/oasis-orchard.webp',null,'https://oasisorchardtech.vercel.app',false,47),
('Nego','Websites','An AI price-negotiation SaaS, landing page and product dashboard. People hesitate to let software negotiate on their behalf, so the interface shows its working: data in view, decisions legible, nothing hidden behind the model.','/portfolio/websites/nego.webp',null,'https://nego-lac.vercel.app',false,48),
('Deliva','Websites','A delivery and logistics web app interface. Designed for people working at speed, so order placement, management and tracking each resolve in as few steps as the data allows.','/portfolio/websites/deliva.webp',null,'https://deliva-web.vercel.app',false,49),
('Vexpense','Websites','An expense-tracking dashboard. The design problem is density: charts and tables carrying real financial detail that still read at a glance on a first look.','/portfolio/websites/vexpense.webp',null,'https://vexpense-client.vercel.app',false,50),
('DTC Nigeria','Websites','A corporate brand website with a content-led structure, built so the company''s own material carries the credibility rather than decoration around it.','/portfolio/websites/dtc-nigeria.webp',null,'https://dtcnigeria.com',false,51),
('Zara Garden Hotel','Websites','A hospitality website with rooms, an image gallery and a booking-enquiry flow. Guests decide on photography, so the gallery leads and the enquiry form stays one tap away throughout.','/portfolio/websites/zara-garden-hotel.webp',null,'https://zaragardenhotel.com',false,52),
('iDOC X','Websites','An unconscious patient cannot tell the doctor their blood group, their allergies or what they are already taking, and the paper file is at a hospital across town. iDOC X gives every Nigerian a scannable health identity that answers those questions in one scan, with the patient deciding who sees what. The site has to sell that to six audiences at once, so patients, hospitals, HMOs, care gifters, travel agencies and blood donors each get their own entry point, alongside AI drug-interaction alerts, a live waitlist and the funding ask.','/portfolio/websites/idocxx.webp',null,'https://idocxx.com',false,53);
insert into testimonials (name, title, company, quote, photo_url, sort_order) values
('WISDOM EKONG','Diagnostic Radiographer & Professional Resume Writer','','He is a great web designer and creator and his prices are affordable. He is highly recommended.',null,0),
('Edidiong Sunday Udoh','Brand Communication & Content Marketing','','Victor is super creative when it comes to creating attractive visual designs. His designs are top-notch and professional. Over time he has lived up to expectations.',null,1),
('Kator Tarkaa','Founder','Fastora','Working with Victor was a great experience from start to finish. He was responsive, open to feedback, and genuinely cared about getting every detail right. We went through several rounds of refinements, and he remained patient throughout, making sure the final website reflected exactly what Fastora stands for. The end result is something we''re genuinely proud of, and I''d happily recommend him to anyone looking for a reliable web developer.','/testimonials/kator-tarkaa.jpg',2);
